<script setup>
import {ref,onMounted} from 'vue'
import {api} from '../services'
const props=defineProps({modelValue:Object,nodes:{type:Array,default:()=>[]}}),emit=defineEmits(['update:modelValue']),catalogs=ref([]),assets=ref([])
const stages=[['fulfillment','Retirada ou entrega'],['address','Endereço'],['cart','Carrinho'],['review','Conferência'],['completed','Pedido enviado']]
const operations=[['add','/add','Adicionar item: /add BUGR1 2'],['remove','/remove','Remover item: /remove BUGR1'],['cart','/pedido','Ver pedido'],['confirm','/confirmar','Conferir pedido e endereço'],['finalize','/finalizar','Enviar pedido confirmado'],['editOrder','/alterar-pedido','Voltar ao carrinho'],['editAddress','/alterar-endereço','Alterar endereço sem perder itens'],['help','/ajuda','Mostrar comandos']]
function current(){return{enabled:false,catalogSlug:'',publicBaseUrl:'',nodes:{},commands:operations.map(([operation,command,description])=>({operation,command,description})),...props.modelValue}}
function update(key,value){emit('update:modelValue',{...current(),[key]:value})}
function stage(key,value){update('nodes',{...current().nodes,[key]:value})}
function command(index,key,value){const items=current().commands.map(c=>({...c}));items[index][key]=value;update('commands',items)}
onMounted(async()=>{try{const responses=await Promise.all([api.get('/catalog'),api.get('/assets',{params:{limit:100}})]);catalogs.value=responses[0].data.items;assets.value=responses[1].data.items}catch{}})
</script>
<template><section class="order-config"><h3>Catálogo, comandos e etapas do pedido</h3><label class="toggle"><input type="checkbox" :checked="current().enabled" @change="update('enabled',$event.target.checked)">Habilitar carrinho neste fluxo</label><template v-if="current().enabled"><label>Catálogo<select :value="current().catalogSlug" @change="update('catalogSlug',$event.target.value)"><option value="">Escolha o catálogo</option><option v-for="c in catalogs" :key="c.slug" :value="c.slug">{{c.title}}</option></select></label><label>URL pública do app<input :value="current().publicBaseUrl" placeholder="https://seu-app.com" @input="update('publicBaseUrl',$event.target.value)"></label><small>Vazio usa PUBLIC_APP_URL do .env; em ambiente local, localhost:8088.</small><div class="stage-selects"><label v-for="[key,title] in stages" :key="key">{{title}}<select :value="current().nodes[key]" @change="stage(key,$event.target.value)"><option value="">Escolha a etapa</option><option v-for="node in nodes" :key="node.nodeId||node.id" :value="node.nodeId||node.id">{{node.data?.label}}</option></select></label></div><label>Imagem de agradecimento<select :value="current().thankYouAssetId||''" @change="update('thankYouAssetId',$event.target.value||null)"><option value="">Sem imagem</option><option v-for="a in assets.filter(a=>a.kind==='image')" :key="a._id" :value="a._id">{{a.name}}</option></select></label><label>Imagem do combo / destaque<select :value="current().comboAssetId||''" @change="update('comboAssetId',$event.target.value||null)"><option value="">Usar imagem do produto em destaque</option><option v-for="a in assets.filter(a=>a.kind==='image')" :key="a._id" :value="a._id">{{a.name}}</option></select></label><label>Mensagem do combo<input :value="current().comboMessage" maxlength="2000" @input="update('comboMessage',$event.target.value)"></label><h4>Comandos que o cliente pode usar</h4><div v-for="(c,index) in current().commands" :key="c.operation" class="command-row"><label>{{operations.find(o=>o[0]===c.operation)?.[2]}}<input :value="c.command" @input="command(index,'command',$event.target.value)"></label><label>Explicação no chat<input :value="c.description" maxlength="200" @input="command(index,'description',$event.target.value)"></label></div><p>As etapas usam o carrinho da conversa. Alterar itens ou endereço invalida a conferência, preserva os produtos e volta ao card escolhido. O estoque só é descontado quando o cliente finaliza.</p></template></section></template>
<style scoped>.order-config{display:grid;gap:16px;padding-top:18px;border-top:1px solid #bfd4c7}.order-config label{display:grid;gap:7px}.order-config .toggle{display:flex;gap:8px}.stage-selects,.command-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.order-config input,.order-config select{width:100%;padding:10px;background:white;color:#19392c;border:1px solid #bdd4c6;border-radius:8px}.order-config input[type=checkbox]{width:auto}.order-config h3,.order-config h4{margin:0}.order-config small,.order-config p{font-size:12px;color:#506b5e;line-height:1.6}@media(max-width:600px){.stage-selects,.command-row{grid-template-columns:1fr}}</style>
